-- (3) 官公庁(government-government-agencies)。種別は 0015 が各サイトに付けた type タグ(label_ja = 台帳の type)から振る。
--     id が pb- で始まるサイトだけが対象(手動掲載の同一サイトは次の URL 照合で拾う)。
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id, CASE t.label_ja WHEN '国の機関' THEN 'national-agencies' WHEN '独立行政法人' THEN 'independent-agencies' WHEN '都道府県' THEN 'prefectures' WHEN '市' THEN 'cities' WHEN '特別区' THEN 'special-wards' WHEN '町' THEN 'towns' WHEN '村' THEN 'villages' WHEN '行政区' THEN 'cities' END FROM site_categories sc JOIN site_tags t ON t.site_id=sc.site_id AND t.label_ja IN ('国の機関','独立行政法人','都道府県','市','特別区','町','村','行政区') WHERE sc.category_id='government-government-agencies' AND sc.site_id LIKE 'pb-%';

--     0015 は URL が既存の手動掲載サイトと重複する団体を新規に入れず、その既存サイト(国立国会図書館 = sample-6)にだけ旧カテゴリを付けた。
--     pb- でないのでタグ経由では拾えない。国の機関・独立行政法人は台帳の URL で照合して葉を付ける(まだ葉の無いサイトだけ)。
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT s.id,'national-agencies' FROM sites s JOIN site_categories sc ON sc.site_id=s.id AND sc.category_id='government-government-agencies' WHERE rtrim(replace(replace(replace(lower(s.url),'https://',''),'http://',''),'www.',''),'/') IN ('jinji.go.jp','soumu.go.jp/kouchoi','kaiho.mlit.go.jp','moj.go.jp/isa','scj.go.jp','jishin.go.jp','mlit.go.jp/kankocho','jma.go.jp/jma','ndl.go.jp','moj.go.jp','npa.go.jp','courts.go.jp','sangiin.go.jp','ppc.go.jp','mext.go.jp','mext.go.jp/sports','reconstruction.go.jp','nta.go.jp','cao.go.jp','mlit.go.jp','jfa.maff.go.jp','moj.go.jp/kouanshin/kouanshinsa_index.html','rinya.maff.go.jp','cas.go.jp','bunka.go.jp','clb.go.jp','npsc.go.jp','fdma.go.jp','digital.go.jp','env.go.jp','sotsui.go.jp','soumu.go.jp','dangai.go.jp','mof.go.jp','japan-acad.go.jp','mlit.go.jp/jmat','kunaicho.go.jp','maff.go.jp','kantei.go.jp','caa.go.jp','fsa.go.jp','mhlw.go.jp','geijutuin.go.jp','mhlw.go.jp/churoi','jcrc.go.jp','jbaudit.go.jp') AND NOT EXISTS (SELECT 1 FROM site_categories x WHERE x.site_id=s.id AND x.category_id IN ('national-agencies','independent-agencies','prefectures','cities','special-wards','towns','villages'));
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT s.id,'independent-agencies' FROM sites s JOIN site_categories sc ON sc.site_id=s.id AND sc.category_id='government-government-agencies' WHERE rtrim(replace(replace(replace(lower(s.url),'https://',''),'http://',''),'www.',''),'/') IN ('ncgm.go.jp','gpif.go.jp','jasso.go.jp','nich.go.jp','artmuseums.go.jp','kahaku.go.jp','inpit.go.jp','jamstec.go.jp','jmets.ac.jp','dnc.ac.jp','nise.go.jp','ncc.go.jp/jp','archives.go.jp','ncnp.go.jp','naltec.go.jp:443','nict.go.jp','pwri.go.jp','riken.jp','niad.ac.jp','jcho.go.jp','rieti.go.jp','erca.go.jp','jpnsport.go.jp','jica.go.jp','nrib.go.jp','johas.go.jp','jetro.go.jp','kouku-dai.ac.jp','pmda.go.jp','mint.go.jp','fra.go.jp','nedo.go.jp','jsps.go.jp','kokusen.go.jp','nho.hosp.go.jp','nozomi.go.jp','ncvc.go.jp','npb.go.jp','nibn.go.jp','nstac.go.jp','niye.go.jp','mpat.go.jp','jaea.go.jp','jpf.go.jp:443','nies.go.jp','nits.go.jp','qst.go.jp','bosai.go.jp','ipa.go.jp','nite.go.jp','hoppou.go.jp') AND NOT EXISTS (SELECT 1 FROM site_categories x WHERE x.site_id=s.id AND x.category_id IN ('national-agencies','independent-agencies','prefectures','cities','special-wards','towns','villages'));

--     それでも葉の無い官公庁カテゴリのサイトは、行政・公的機関(トップ)に置く(想定は 0 件。件数は PR の検証で確認する)。
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id,'government' FROM site_categories sc WHERE sc.category_id='government-government-agencies' AND NOT EXISTS (SELECT 1 FROM site_categories x WHERE x.site_id=sc.site_id AND x.category_id IN ('national-agencies','independent-agencies','prefectures','cities','special-wards','towns','villages'));

-- (4) 退避先(mode=fallback)。主題でなく運営主体・地域だった旧カテゴリ。ここまでの手順で退避先でない新カテゴリ(keep/map/rule)を 1 つも持たないサイトにだけ、退避先をすべて付ける(再判定で主題へ移す前提)。
--     1 文ずつ順に付けると先に付いた退避先が「他にある」と数えられて後の退避先が付かないので、判定は手順 4 の前に作る一時表(_taxonomy_pre)に固定する。
CREATE TABLE _taxonomy_pre AS SELECT DISTINCT site_id FROM site_categories WHERE category_id NOT IN ('arts-humanities','arts-photography','arts-architecture','arts-museums-and-galleries','news','news-world-news','news-newspapers','news-current-affairs','business-companies','business-organizations','business-products-and-services','business-jobs','recreation','recreation-sports','recreation-games','recreation-travel','recreation-cars','computers','computers-internet','computers-software','computers-multimedia','reference-libraries','reference-dictionaries','education-universities','education-schools','education-courses','local','local-japan','local-world','entertainment-television','entertainment-film','entertainment-music','entertainment-magazines','science-computing','science-biology','science-astronomy','science-engineering','government-politics','government-government-agencies','government-research-institutes','social-science','social-science-economics','social-science-sociology','social-science-archaeology','health-medicine','health-hospitals','health-healthcare','health-nutrition','society-environment','society-religion');
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id,'business' FROM site_categories sc WHERE sc.category_id='business-companies' AND sc.site_id NOT IN (SELECT site_id FROM _taxonomy_pre);
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id,'society' FROM site_categories sc WHERE sc.category_id='business-organizations' AND sc.site_id NOT IN (SELECT site_id FROM _taxonomy_pre);
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id,'business-services' FROM site_categories sc WHERE sc.category_id='business-products-and-services' AND sc.site_id NOT IN (SELECT site_id FROM _taxonomy_pre);
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id,'community' FROM site_categories sc WHERE sc.category_id='local' AND sc.site_id NOT IN (SELECT site_id FROM _taxonomy_pre);
INSERT OR IGNORE INTO site_categories (site_id,category_id) SELECT sc.site_id,'community' FROM site_categories sc WHERE sc.category_id='local-japan' AND sc.site_id NOT IN (SELECT site_id FROM _taxonomy_pre);
DROP TABLE _taxonomy_pre;

-- (5) 検査。旧カテゴリしか持たないサイトが 1 件でも残っていれば CHECK 違反でこの migration 全体が失敗する(旧カテゴリを消す前に止める)。
CREATE TABLE _taxonomy_check (orphans INTEGER NOT NULL CHECK (orphans = 0));
DROP TABLE _taxonomy_check;

